return {["fb213_01"]={["down"]=[[fb213_15]],["dsc"]=[[此处是连接两层楼的楼道。楼道全由实木建成，设有栏杆，漆有红漆。栏杆上雕花细致，似是大家手笔。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb213_01]],["item1"]=[[tllt1]],["item2"]=[[tldj2]],["item3"]=[[tldj3]],["name"]=[[楼道]],["permission"]=1,["right"]=[[fb213_11]],["stepMusic"]=[[jiaobu]],["up"]=[[fb213_08]]},["fb213_02"]={["down"]=[[fb213_08]],["dsc"]=[[此处是走廊转角处的回廊。回廊是木质，其上铺有毛毯，踩上去柔软舒适。回廊的廊柱均是以浮雕装饰，颇为不凡。廊柱之下摆放有凳子，可供人休息。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb213_02]],["name"]=[[回廊]],["permission"]=1,["right"]=[[fb213_03]],["stepMusic"]=[[jiaobu]]},["fb213_03"]={["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb213_03]],["item1"]=[[213dj9]],["left"]=[[fb213_02]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb213_04]],["stepMusic"]=[[jiaobu]]},["fb213_04"]={["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb213_04]],["item1"]=[[213dj10]],["left"]=[[fb213_03]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb213_05]],["stepMusic"]=[[jiaobu]]},["fb213_05"]={["down"]=[[fb213_09]],["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb213_05]],["item1"]=[[213dj11]],["left"]=[[fb213_04]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb213_06]],["stepMusic"]=[[jiaobu]]},["fb213_06"]={["down"]=[[fb213_30]],["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb213_06]],["left"]=[[fb213_05]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb213_07]],["stepMusic"]=[[jiaobu]]},["fb213_07"]={["down"]=[[fb213_10]],["dsc"]=[[此处是走廊转角处的回廊。回廊是木质，其上铺有毛毯，踩上去柔软舒适。回廊的廊柱均是以浮雕装饰，颇为不凡。廊柱之下摆放有凳子，可供人休息。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb213_07]],["left"]=[[fb213_06]],["name"]=[[回廊]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb213_08"]={["down"]=[[fb213_01]],["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔